# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _require_email(student: Student) -> None:
    if not (student.email or "").strip():
        name = student.display_name
        raise ProjectError(f"no email for {name}")


def _cells(student: Student) -> List[str]:
    email = student.email.strip()
    return [student.display_name, student.section, email]


def _widths(cells: List[List[str]]) -> List[int]:
    return [max(len(c) for c in col) for col in zip(*cells)]


def _line(row: List[str], widths: List[int]) -> str:
    parts = [c.ljust(w) for c, w in zip(row, widths)]
    return "  ".join(parts).rstrip()


# ---
def format_contacts(students: Sequence[Student]) -> List[str]:
    """One aligned row per student, sorted by display name."""
    if not students:
        raise ProjectError("no students for the contact sheet")
    for student in students:
        _require_email(student)
    ordered = sorted(students, key=lambda s: s.display_name)
    cells = [_cells(s) for s in ordered]
    return [_line(c, _widths(cells)) for c in cells]
