# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts


def make(last, first, section, email="x@school.org"):
    return Student("1", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = format_contacts([
            make("Thistle", "Bram", "A", "bram@s.org"),
            make("Ames", "Jo", "B", "jo@s.org")
        ])
        self.assertEqual(rows, [
            "Ames, Jo        B  jo@s.org",
            "Thistle, Bram   A  bram@s.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            format_contacts([make("Ames", "Jo", "A", None)])
        self.assertIn("Ames, Jo", str(ctx.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            format_contacts([make("Ames", "Jo", "A", "  ")])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            format_contacts([])


if __name__ == "__main__":
    unittest.main()
